parameters.jsCode:
// Ventana de tiempo en minutos para evitar duplicados sin persistencia externa
const VENTANA_MINUTOS = 20;
const MIN_MAGNITUD = 4.0;

const rawData = $input.first().json;
const features = rawData.features || [];

const ahora = Date.now();
const limiteTiempo = ahora - (VENTANA_MINUTOS * 60 * 1000);

// Filtrar sismos que hayan ocurrido dentro de la ventana de los últimos 20 minutos
const sismosRecientes = features.filter(item => {
  const t = item.properties.time;
  const mag = item.properties.mag;
  return t >= limiteTiempo && mag >= MIN_MAGNITUD;
});

if (sismosRecientes.length === 0) {
  return [{
    json: {
      alerta_activa: false,
      total_sismos: 0,
      mensaje: `Sin sismos detectados en el radio monitoreado en los últimos ${VENTANA_MINUTOS} minutos.`
    }
  }];
}

// Retornar cada sismo como un item individual para n8n
return sismosRecientes.map(item => {
  const props = item.properties;
  const coords = item.geometry ? item.geometry.coordinates : [0, 0, 0];
  const fechaEvento = new Date(props.time).toLocaleString('es-CL', { timeZone: 'America/Santiago' });

  return {
    json: {
      alerta_activa: true,
      id: item.id,
      magnitud: props.mag,
      lugar: props.place || 'Chile Central',
      profundidad_km: coords[2] || 0,
      longitud: coords[0],
      latitud: coords[1],
      hora_local: fechaEvento,
      url_usgs: props.url,
      total_sismos: sismosRecientes.length
    }
  };
});

